import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    private static final int[][] NEIGHBORS = {
            {-1, -1}, {-1, 0}, {-1, 1},
            {0, -1}, {0, 0}, {0, 1},
            {1, -1}, {1, 0}, {1, 1}
    };

    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Map<Integer, Integer> rows = new HashMap<>();
        Map<Integer, Integer> cols = new HashMap<>();
        Map<Integer, Integer> diagonals = new HashMap<>();
        Map<Integer, Integer> antiDiagonals = new HashMap<>();
        Set<Long> active = new HashSet<>();

        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            long key = encode(row, col);
            if (active.add(key)) {
                increment(rows, row);
                increment(cols, col);
                increment(diagonals, row - col);
                increment(antiDiagonals, row + col);
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];
            if (count(rows, row) > 0 || count(cols, col) > 0
                    || count(diagonals, row - col) > 0 || count(antiDiagonals, row + col) > 0) {
                answer[i] = 1;
            }

            for (int[] delta : NEIGHBORS) {
                int nextRow = row + delta[0];
                int nextCol = col + delta[1];
                if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
                    continue;
                }
                long key = encode(nextRow, nextCol);
                if (active.remove(key)) {
                    decrement(rows, nextRow);
                    decrement(cols, nextCol);
                    decrement(diagonals, nextRow - nextCol);
                    decrement(antiDiagonals, nextRow + nextCol);
                }
            }
        }
        return answer;
    }

    private long encode(int row, int col) {
        return ((long) row << 32) ^ (col & 0xffffffffL);
    }

    private int count(Map<Integer, Integer> map, int key) {
        return map.getOrDefault(key, 0);
    }

    private void increment(Map<Integer, Integer> map, int key) {
        map.merge(key, 1, Integer::sum);
    }

    private void decrement(Map<Integer, Integer> map, int key) {
        int next = map.get(key) - 1;
        if (next == 0) {
            map.remove(key);
        } else {
            map.put(key, next);
        }
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Map<Long, Integer> lineCount = new HashMap<>();
        Set<Long> active = new HashSet<>();

        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            long lampKey = encodeLamp(row, col);
            if (active.add(lampKey)) {
                addLines(lineCount, row, col, 1);
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];
            if (lineCount.getOrDefault(lineKey(0, row), 0) > 0
                    || lineCount.getOrDefault(lineKey(1, col), 0) > 0
                    || lineCount.getOrDefault(lineKey(2, row - col), 0) > 0
                    || lineCount.getOrDefault(lineKey(3, row + col), 0) > 0) {
                answer[i] = 1;
            }

            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nextRow = row + dr;
                    int nextCol = col + dc;
                    if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
                        continue;
                    }
                    long lampKey = encodeLamp(nextRow, nextCol);
                    if (active.remove(lampKey)) {
                        addLines(lineCount, nextRow, nextCol, -1);
                    }
                }
            }
        }
        return answer;
    }

    private void addLines(Map<Long, Integer> lineCount, int row, int col, int delta) {
        update(lineCount, lineKey(0, row), delta);
        update(lineCount, lineKey(1, col), delta);
        update(lineCount, lineKey(2, row - col), delta);
        update(lineCount, lineKey(3, row + col), delta);
    }

    private void update(Map<Long, Integer> map, long key, int delta) {
        int next = map.getOrDefault(key, 0) + delta;
        if (next == 0) {
            map.remove(key);
        } else {
            map.put(key, next);
        }
    }

    private long lineKey(int type, int value) {
        return ((long) type << 32) ^ (value & 0xffffffffL);
    }

    private long encodeLamp(int row, int col) {
        return ((long) row << 32) ^ (col & 0xffffffffL);
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Map<Integer, Set<Long>> rows = new HashMap<>();
        Map<Integer, Set<Long>> cols = new HashMap<>();
        Map<Integer, Set<Long>> diagonals = new HashMap<>();
        Map<Integer, Set<Long>> antiDiagonals = new HashMap<>();
        Set<Long> active = new HashSet<>();

        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            long key = encode(row, col);
            if (active.add(key)) {
                add(rows, row, key);
                add(cols, col, key);
                add(diagonals, row - col, key);
                add(antiDiagonals, row + col, key);
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];
            if (has(rows, row) || has(cols, col) || has(diagonals, row - col) || has(antiDiagonals, row + col)) {
                answer[i] = 1;
            }

            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nextRow = row + dr;
                    int nextCol = col + dc;
                    if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
                        continue;
                    }
                    long key = encode(nextRow, nextCol);
                    if (active.remove(key)) {
                        remove(rows, nextRow, key);
                        remove(cols, nextCol, key);
                        remove(diagonals, nextRow - nextCol, key);
                        remove(antiDiagonals, nextRow + nextCol, key);
                    }
                }
            }
        }
        return answer;
    }

    private void add(Map<Integer, Set<Long>> lines, int line, long lamp) {
        lines.computeIfAbsent(line, ignored -> new HashSet<>()).add(lamp);
    }

    private boolean has(Map<Integer, Set<Long>> lines, int line) {
        Set<Long> lamps = lines.get(line);
        return lamps != null && !lamps.isEmpty();
    }

    private void remove(Map<Integer, Set<Long>> lines, int line, long lamp) {
        Set<Long> lamps = lines.get(line);
        if (lamps == null) {
            return;
        }
        lamps.remove(lamp);
        if (lamps.isEmpty()) {
            lines.remove(line);
        }
    }

    private long encode(int row, int col) {
        return ((long) row << 32) ^ (col & 0xffffffffL);
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Map<Integer, Integer> rowIndex = new HashMap<>();
        Map<Integer, Integer> colIndex = new HashMap<>();
        Map<Integer, Integer> diagonalIndex = new HashMap<>();
        Map<Integer, Integer> antiIndex = new HashMap<>();

        for (int[] lamp : lamps) {
            register(rowIndex, lamp[0]);
            register(colIndex, lamp[1]);
            register(diagonalIndex, lamp[0] - lamp[1]);
            register(antiIndex, lamp[0] + lamp[1]);
        }
        for (int[] query : queries) {
            register(rowIndex, query[0]);
            register(colIndex, query[1]);
            register(diagonalIndex, query[0] - query[1]);
            register(antiIndex, query[0] + query[1]);
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int row = query[0] + dr;
                    int col = query[1] + dc;
                    if (row >= 0 && row < n && col >= 0 && col < n) {
                        register(rowIndex, row);
                        register(colIndex, col);
                        register(diagonalIndex, row - col);
                        register(antiIndex, row + col);
                    }
                }
            }
        }

        int[] rows = new int[rowIndex.size()];
        int[] cols = new int[colIndex.size()];
        int[] diagonals = new int[diagonalIndex.size()];
        int[] antiDiagonals = new int[antiIndex.size()];
        Set<Long> active = new HashSet<>();

        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            long key = encode(row, col);
            if (active.add(key)) {
                rows[rowIndex.get(row)]++;
                cols[colIndex.get(col)]++;
                diagonals[diagonalIndex.get(row - col)]++;
                antiDiagonals[antiIndex.get(row + col)]++;
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];
            if (rows[rowIndex.get(row)] > 0 || cols[colIndex.get(col)] > 0
                    || diagonals[diagonalIndex.get(row - col)] > 0
                    || antiDiagonals[antiIndex.get(row + col)] > 0) {
                answer[i] = 1;
            }

            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nextRow = row + dr;
                    int nextCol = col + dc;
                    if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
                        continue;
                    }
                    long key = encode(nextRow, nextCol);
                    if (active.remove(key)) {
                        rows[rowIndex.get(nextRow)]--;
                        cols[colIndex.get(nextCol)]--;
                        diagonals[diagonalIndex.get(nextRow - nextCol)]--;
                        antiDiagonals[antiIndex.get(nextRow + nextCol)]--;
                    }
                }
            }
        }
        return answer;
    }

    private void register(Map<Integer, Integer> index, int value) {
        index.computeIfAbsent(value, ignored -> index.size());
    }

    private long encode(int row, int col) {
        return ((long) row << 32) ^ (col & 0xffffffffL);
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Map<Integer, Integer> rows = new HashMap<>();
        Map<Integer, Integer> cols = new HashMap<>();
        Map<Integer, Integer> diagonals = new HashMap<>();
        Map<Integer, Integer> antiDiagonals = new HashMap<>();
        Map<Integer, Set<Integer>> activeByRow = new HashMap<>();

        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            Set<Integer> rowSet = activeByRow.computeIfAbsent(row, ignored -> new HashSet<>());
            if (rowSet.add(col)) {
                add(rows, row, 1);
                add(cols, col, 1);
                add(diagonals, row - col, 1);
                add(antiDiagonals, row + col, 1);
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];
            if (rows.getOrDefault(row, 0) > 0 || cols.getOrDefault(col, 0) > 0
                    || diagonals.getOrDefault(row - col, 0) > 0
                    || antiDiagonals.getOrDefault(row + col, 0) > 0) {
                answer[i] = 1;
            }

            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nextRow = row + dr;
                    int nextCol = col + dc;
                    if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
                        continue;
                    }
                    Set<Integer> rowSet = activeByRow.get(nextRow);
                    if (rowSet != null && rowSet.remove(nextCol)) {
                        if (rowSet.isEmpty()) {
                            activeByRow.remove(nextRow);
                        }
                        add(rows, nextRow, -1);
                        add(cols, nextCol, -1);
                        add(diagonals, nextRow - nextCol, -1);
                        add(antiDiagonals, nextRow + nextCol, -1);
                    }
                }
            }
        }
        return answer;
    }

    private void add(Map<Integer, Integer> map, int key, int delta) {
        int next = map.getOrDefault(key, 0) + delta;
        if (next == 0) {
            map.remove(key);
        } else {
            map.put(key, next);
        }
    }
}
